code.snippet:
body.t-midnight .hero h1 { font-weight: 800; letter-spacing: -2px; }
body.t-midnight .section-title { letter-spacing: -1px; }
body.t-midnight .section-tag { border: none; background: var(--surface); letter-spacing: 4px; font-size: 11.5px; }
body.t-midnight .card:hover { background: rgba(59,130,246,.04); }
body.t-midnight .card.featured { border-color: rgba(59,130,246,.45); }
body.t-midnight .btn-primary:hover { box-shadow: 0 0 32px rgba(59,130,246,.4); }
body.t-midnight .bar-fill { background: var(--accent); }
body.t-midnight .hero-badge i { animation: none; }
body.t-midnight .stat b { font-weight: 800; }
body.t-midnight .contact-ico svg { fill: var(--text); }
